139	  owned.child = child;
140	  owned.port = port;
141	  owned.pgid = child.pid ?? null;
142	
143	  child.stdout?.on('data', (chunk) => forward('app.stdout', chunk));
144	  child.stderr?.on('data', (chunk) => forward('app.stderr', chunk));
145	  child.once('error', (error) => {
146	    owned.spawnError = error;
147	    log('app.spawn_error', { code: error.code, message: error.message });
148	  });
149	  child.once('exit', (code, signal) => {
150	    owned.exit = { code, signal };
151	    log('app.exit', { pid: child.pid, code, signal });
152	  });
153	
154	  log('app.spawn', {
155	    pid: child.pid,
156	    pgid: owned.pgid,
157	    port,
158	    cwd: PKG_ROOT,
159	    command: 'npm run start',
160	    log_path: owned.logPath,
161	  });
162	  return child;
163	}
164	
165	function forward(event, chunk) {
166	  for (const line of chunk.toString().split('\n')) {
167	    if (line.trim()) log(event, { line: line.trimEnd() });
168	  }
169	}
170	
171	/** Poll the shipped route until it answers the readiness contract or the deadline passes. */
172	async function waitForReady(port) {
173	  const url = `http://${HOST}:${port}${READY_PATH}`;
174	  const deadline = Date.now() + READY_TIMEOUT_MS;
175	  let attempts = 0;
176	  let lastError = 'no attempt completed';
177	
178	  while (Date.now() < deadline) {
179	    if (owned.spawnError) {
180	      const kind = owned.spawnError.code === 'ENOENT' ? 'runner/start_command_unavailable' : 'app/exited_early';
181	      throw new BootError(kind, `could not run "npm run start": ${owned.spawnError.message}`);
182	    }
183	    if (owned.exit) {
184	      const { code, signal } = owned.exit;
185	      throw new BootError('app/exited_early', `child exited (code=${code}, signal=${signal}) before ${READY_PATH} answered`);
186	    }
187	    attempts += 1;
188	    try {
189	      const res = await fetch(url, { signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
190	      if (!res.ok) {
191	        lastError = `HTTP ${res.status}`;
192	      } else {
193	        const body = await res.json();
194	        if (!Array.isArray(body)) {
195	          throw new BootError('app/readiness_contract', `${READY_PATH} returned ${typeof body}, expected an array`);
196	        }
197	        log('app.ready', { url, attempts, status: res.status, items: body.length });
198	        return { url, attempts };
199	      }
200	    } catch (error) {
201	      if (error instanceof BootError) throw error;
202	      lastError = error.message;
203	    }
204	    await sleep(POLL_INTERVAL_MS);
205	  }
206	  throw new BootError('app/readiness_timeout', `${url} not ready within ${READY_TIMEOUT_MS}ms (last: ${lastError})`);
207	}
208	
209	/** Signal the owned process group only — never by name — then confirm it is gone. */
210	async function stopApp() {
211	  if (stopping) return stopping;
212	  stopping = (async () => {
213	    const { child, pgid, port } = owned;
214	    if (!child || child.pid == null) return { released: true };
215	    if (owned.exit) return verifyReleased(child.pid, port);
216	
217	    signalOwned(pgid, child.pid, 'SIGTERM');
218	    const deadline = Date.now() + STOP_TIMEOUT_MS;
219	    while (!owned.exit && Date.now() < deadline) await sleep(50);
220	    if (!owned.exit) {
221	      log('app.stop.escalate', { pid: child.pid, signal: 'SIGKILL' });
222	      signalOwned(pgid, child.pid, 'SIGKILL');
223	      const hard = Date.now() + STOP_TIMEOUT_MS;
224	      while (!owned.exit && Date.now() < hard) await sleep(50);
225	    }
226	    return verifyReleased(child.pid, port);
227	  })();
228	  return stopping;
229	}
230	
231	function signalOwned(pgid, pid, signal) {
232	  for (const target of pgid ? [-pgid, pid] : [pid]) {
233	    try {
234	      process.kill(target, signal);
235	      if (target < 0) return; // the group covers the direct child too
236	    } catch (error) {
237	      if (error.code !== 'ESRCH' && error.code !== 'EPERM') throw error;
238	    }
239	  }
240	}
241	
242	/** Grade final state instead of trusting the kill's exit status. */
243	async function verifyReleased(pid, port) {
244	  let alive = false;
245	  try {
246	    process.kill(pid, 0);
247	    alive = true;
248	  } catch {
249	    alive = false;
250	  }
251	  const portBusy = port ? await isListening(port) : false;
252	  const released = !alive && !portBusy;
253	  log('app.stop', { pid, port, released, process_alive: alive, port_listening: portBusy });
254	  return { released, alive, portBusy };
255	}
256	
257	function finish(outcome, extra = {}) {
258	  log('lifecycle', { outcome, keep: KEEP, port: owned.port, ...extra });
259	}
260	
261	async function failAndExit(error, startedAt) {
262	  const kind = error instanceof BootError ? error.kind : 'app/unknown';
263	  const cleanup = await stopApp().catch((e) => ({ released: false, alive: true, portBusy: false, error: e.message }));
264	  finish('failed', {
265	    error_kind: kind,
266	    detail: error.message,
267	    recovery: RECOVERY[kind] ?? 'inspect the output above',
268	    duration_ms: Date.now() - startedAt,
269	    cleanup_released: cleanup.released !== false,
270	  });
271	  process.exit(1);
272	}
273	
274	async function main() {
275	  const startedAt = Date.now();
276	
277	  // Register teardown before anything can be raised, so every exit path releases.
278	  for (const signal of ['SIGINT', 'SIGTERM']) {
279	    process.on(signal, async () => {
280	      await stopApp().catch(() => {});
281	      finish('signaled', { signal, duration_ms: Date.now() - startedAt });
282	      process.exit(128 + (signal === 'SIGINT' ? 2 : 15));
283	    });
284	  }
285	
286	  let port;
287	  try {
288	    preflight();
289	    port = await choosePort();
290	  } catch (error) {
291	    return failAndExit(error, startedAt);
292	  }
293	
294	  let child;
295	  try {
296	    child = startApp(port);
297	    const ready = await waitForReady(port);
298	
299	    if (KEEP) {
300	      child.unref();
301	      const teardown = owned.pgid ? `kill -TERM -${owned.pgid}` : `kill -TERM ${child.pid}`;
302	      finish('ready', {
303	        handoff: { pid: child.pid, pgid: owned.pgid, url: ready.url, log_path: owned.logPath, teardown },
304	        duration_ms: Date.now() - startedAt,
305	      });
306	      process.exit(0);
307	    }
308	
309	    const cleanup = await stopApp();
310	    if (!cleanup.released) {
311	      // Primary work succeeded; a leaked resource still fails the command.
312	      finish('failed', {
313	        error_kind: 'app/teardown_failed',
314	        detail: `pid ${child.pid} alive=${cleanup.alive} port_listening=${cleanup.portBusy}`,
315	        recovery: RECOVERY['app/teardown_failed'],
316	        duration_ms: Date.now() - startedAt,
317	      });
318	      process.exit(1);
319	    }
320	    finish('ready', { url: ready.url, attempts: ready.attempts, duration_ms: Date.now() - startedAt });
321	    process.exit(0);
322	  } catch (error) {
323	    return failAndExit(error, startedAt);
324	  }
325	}
326	
327	main();
